import Foundation
enum UILanguage: String, CaseIterable {
    case uk, en, ru
    static var initial: UILanguage {
        let code = Locale.preferredLanguages.first ?? "uk"
        if code.hasPrefix("en") { return .en }; if code.hasPrefix("ru") { return .ru }; return .uk
    }
    var name: String { switch self { case .uk: return "Українська"; case .en: return "English"; case .ru: return "Русский" } }
}
